-- Import Category, Genre, Country from Website PL Data Final.csv
-- Columns used: B=ID, C=Title, D=Category, E=Genre, F=Account, G=Master, S=Country

ALTER TABLE ads_playlist_settings
  ADD COLUMN IF NOT EXISTS playlist_id TEXT,
  ADD COLUMN IF NOT EXISTS playlist_name TEXT,
  ADD COLUMN IF NOT EXISTS category TEXT,
  ADD COLUMN IF NOT EXISTS genre TEXT,
  ADD COLUMN IF NOT EXISTS country TEXT,
  ADD COLUMN IF NOT EXISTS account_name TEXT,
  ADD COLUMN IF NOT EXISTS master_playlist TEXT,
  ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP DEFAULT NOW();

CREATE UNIQUE INDEX IF NOT EXISTS ads_playlist_settings_playlist_id_key
ON ads_playlist_settings (playlist_id);

ON CONFLICT (playlist_id) DO UPDATE SET
  playlist_name = EXCLUDED.playlist_name,
  category = EXCLUDED.category,
  genre = EXCLUDED.genre,
  country = EXCLUDED.country,
  account_name = EXCLUDED.account_name,
  master_playlist = EXCLUDED.master_playlist,
  updated_at = NOW();

-- Verify import
SELECT playlist_id, playlist_name, category, genre, country, account_name, master_playlist, updated_at
FROM ads_playlist_settings
ORDER BY updated_at DESC
LIMIT 50;